import {channels,aggregate,growth,parseCSV,validateRows} from './core.js';import {LocalRepository} from './repository.js';import {readXLSX} from './xlsx.js';
const $=s=>document.querySelector(s),fmt=n=>n.toLocaleString('ko-KR'),esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));let repo,records=[],events=[],pending=[],active='overview';const titles={overview:'통합 대시보드',schedule:'콘텐츠 일정',data:'데이터 관리',report:'월간 보고서'};for(let i=1;i<=12;i++)$('#month').insertAdjacentHTML('beforeend',`<option value="${i}">${i}월</option>`);$('#month').value='10';
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('show');setTimeout(()=>$('#toast').classList.remove('show'),4000);}
const year=()=>$('#year').value,month=()=>$('#month').value,channel=()=>$('#channel').value;const selectedChannels=()=>Object.keys(channels).filter(c=>channel()==='all'||channel()===c);const matching=(r,annual=false)=>r.month.startsWith(year()+'-')&&(annual||month()==='all'||+r.month.slice(5)===+month())&&(channel()==='all'||r.channel===channel());const filtered=()=>records.filter(r=>matching(r));const period=()=>`${year()}년 ${month()==='all'?'연간 누적':month()+'월'} · ${channel()==='all'?'전체 채널':channels[channel()].name}`;
function previous(c){if(month()==='all')return null;const d=new Date(+year(),+month()-2,1);const key=`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}`;const prev=records.filter(r=>r.month===key&&r.channel===c);return prev.length?aggregate(prev).impressions:null;}
function comparison(c,now){const prev=previous(c);return month()==='all'?'연간 누적 · 전월 비교 제외':prev===null?'전월 데이터 없음':`전월 대비 ${growth(now,prev)}`;}
function render(){const rows=filtered();$('#period-label').textContent=period();$('#kpis').innerHTML=selectedChannels().map(c=>{const ch=channels[c],rs=rows.filter(r=>r.channel===c),a=aggregate(rs);return `<article class="kpi"><div class="kpi-head"><span class="channel-icon ${c==='linkedin'?'li-bg':c==='instagram'?'ig-bg':''}">${ch.icon}</span>${ch.name}<small>${rs.length?'집계 완료':'데이터 없음'}</small></div><div class="metric-label">${c==='youtube'?'조회수':'노출수'}</div><div class="metric">${fmt(a.impressions)}</div><div class="delta ${previous(c)>a.impressions?'negative':''}">${esc(comparison(c,a.impressions))}</div><div class="kpi-bottom"><div><span>참여</span><strong>${fmt(a.engagement)}</strong></div><div><span>팔로워 증가</span><strong>+${fmt(a.followers)}</strong></div></div></article>`;}).join('');$('#kpis').style.gridTemplateColumns=`repeat(${selectedChannels().length}, minmax(0,1fr))`;if(innerWidth<560)$('#kpis').style.gridTemplateColumns='1fr';renderChart();$('#goals').innerHTML=selectedChannels().map(c=>{const a=aggregate(records.filter(r=>r.channel===c&&r.month.startsWith(year()))).impressions,ch=channels[c],pct=a/ch.target*100;return `<div class="goal"><div class="goal-top"><span>${ch.name}</span><b style="color:${ch.color}">${pct.toFixed(1)}%</b></div><div class="bar"><i style="width:${Math.min(100,pct)}%;background:${ch.color}"></i></div><div class="goal-bottom"><span>${fmt(a)}</span><span>목표 ${fmt(ch.target)}</span></div></div>`;}).join('');const es=events.filter(e=>matching({month:e.date.slice(0,7),channel:e.channel})).sort((a,b)=>a.date.localeCompare(b.date));$('#upcoming').innerHTML=eventRows(es.slice(0,3),false);$('#schedule-list').innerHTML=eventRows(es,true);const a=aggregate(rows),best=selectedChannels().map(c=>({c,n:aggregate(rows.filter(r=>r.channel===c)).impressions})).sort((a,b)=>b.n-a.n)[0];$('#insights').innerHTML=`<div class="insight-item"><span>↗</span><div><b>${a.impressions?channels[best.c].name+'에서 가장 많은 조회·노출을 기록했어요.':'선택 기간의 실적 데이터가 없습니다.'}</b><p>${a.impressions?`${fmt(best.n)}회의 조회·노출을 기록했습니다. 채널마다 집계 기준이 다르므로 추세를 함께 살펴보세요.`:'기간을 변경하거나 데이터 관리에서 실적을 업로드하세요.'}</p></div></div><div class="insight-item"><span>▦</span><div><b>${es.filter(e=>e.status!=='업로드 완료').length}개의 콘텐츠가 발행을 준비하고 있어요.</b><p>선택 기간 ${es.length}건 중 ${es.filter(e=>e.status==='업로드 완료').length}건이 업로드 완료 상태입니다. 콘텐츠 일정에서 진행 상황을 관리하세요.</p></div></div>`;$('#data-table').innerHTML=table(rows);$('#report-body').innerHTML=reportBody();}
function renderChart(){const W=650,H=240,L=48,R=15,T=20,B=35,visible=selectedChannels(),points=Array.from({length:12},(_,i)=>Object.fromEntries(visible.map(c=>[c,records.find(r=>r.channel===c&&r.month===`${year()}-${String(i+1).padStart(2,'0')}`)?.impressions??null])));const max=Math.max(10000,...points.flatMap(p=>Object.values(p).filter(v=>v!==null)))*1.2;const x=i=>L+i*(W-L-R)/11,y=n=>H-B-n/max*(H-T-B);let svg=`<svg viewBox="0 0 ${W} ${H}" role="img" aria-label="${year()}년 채널별 월별 조회 및 노출 추이"><defs>${visible.map(c=>`<linearGradient id="fill-${c}" x1="0" y1="0" x2="0" y2="1"><stop stop-color="${channels[c].color}" stop-opacity=".14"/><stop offset="1" stop-color="${channels[c].color}" stop-opacity="0"/></linearGradient>`).join('')}</defs>`;for(let i=0;i<=4;i++){const n=max*i/4;svg+=`<line x1="${L}" y1="${y(n)}" x2="${W-R}" y2="${y(n)}" stroke="#253347" stroke-dasharray="3 5"/><text x="${L-9}" y="${y(n)+3}" text-anchor="end" fill="#71849e" font-size="9">${Math.round(n/10000)}만</text>`;}for(let i=0;i<12;i++)svg+=`<text x="${x(i)}" y="${H-10}" text-anchor="middle" fill="${+month()===i+1?'#64e9c0':'#71849e'}" font-size="9">${i+1}월</text>`;for(const c of visible){let segment=[];const draw=()=>{if(!segment.length)return;const path=segment.map(([i,n],k)=>`${k?'L':'M'}${x(i)},${y(n)}`).join(' ');svg+=`<path d="${path} L${x(segment.at(-1)[0])},${H-B} L${x(segment[0][0])},${H-B}Z" fill="url(#fill-${c})"/><path d="${path}" fill="none" stroke="${channels[c].color}" stroke-width="2.5"/>`;segment=[];};points.forEach((p,i)=>{if(p[c]===null)draw();else segment.push([i,p[c]]);});draw();points.forEach((p,i)=>{if(p[c]!==null)svg+=`<circle cx="${x(i)}" cy="${y(p[c])}" r="${+month()===i+1?4:2.5}" fill="${channels[c].color}"><title>${i+1}월 ${channels[c].name}: ${fmt(p[c])}회</title></circle>`;});}svg+='</svg>';$('#chart').innerHTML=svg+'<p class="help" style="margin:0;text-align:right;font-size:9px">연간 추이 · 점에 마우스를 올리면 수치 확인 · 빈 월은 미집계</p>';}
function eventRows(es,editable){return es.length?es.map(e=>`<div class="schedule-row"><div class="date-box"><small>${+e.date.slice(5,7)}월</small>${+e.date.slice(8)}</div><div class="event-info"><strong>${esc(e.title)}</strong><small>${channels[e.channel].name} · ${e.date}</small></div><span class="status ${e.status==='업로드 완료'?'done':''}">${esc(e.status)}</span>${editable?`<button class="text-btn" data-edit="${esc(e.id)}">수정</button><button class="text-btn error" data-delete="${esc(e.id)}">삭제</button>`:''}</div>`).join(''):'<div class="empty">선택 기간에 등록된 일정이 없습니다.</div>';}
function table(rs){return rs.length?`<table><thead><tr>${['월','채널','조회·노출','참여','팔로워 증가','출처'].map(t=>`<th>${t}</th>`).join('')}</tr></thead><tbody>${rs.map(r=>`<tr><td>${esc(r.month)}</td><td>${channels[r.channel].name}</td><td>${fmt(r.impressions)}</td><td>${fmt(r.engagement)}</td><td>${fmt(r.followers)}</td><td>${r.source==='sample'?'샘플':'업로드'}</td></tr>`).join('')}</tbody></table>`:'<div class="empty">선택 기간의 데이터가 없습니다.</div>';}
function reportBody(){const a=aggregate(filtered());return `<p class="eyebrow">${period()}</p><h2>현대무벡스 디지털 마케팅 실적 요약</h2><p class="help">샘플 데이터 포함 · 실제 회사 실적 아님 · 조회수와 노출수는 채널별 정의가 다릅니다.</p><div class="report-metrics"><div><span>총 조회·노출</span><b>${fmt(a.impressions)}</b></div><div><span>총 참여</span><b>${fmt(a.engagement)}</b></div><div><span>팔로워 증가 합계</span><b>+${fmt(a.followers)}</b></div></div>${selectedChannels().map(c=>{const n=aggregate(filtered().filter(r=>r.channel===c)).impressions;const annual=aggregate(records.filter(r=>r.channel===c&&r.month.startsWith(year()))).impressions;return `<p>${channels[c].name}: ${fmt(n)}회 · ${esc(comparison(c,n))} · 연간 목표 달성률 ${(annual/channels[c].target*100).toFixed(1)}%</p>`;}).join('')}${table(filtered())}`;}
function download(name,content,type){const url=URL.createObjectURL(new Blob([content],{type})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),3000);}
function reportDownload(){download(`현대무벡스_샘플포함_마케팅보고서_${year()}-${month()}.html`,`<!doctype html><html lang="ko"><meta charset="utf-8"><title>마케팅 실적 보고서</title><style>body{font:14px/1.8 sans-serif;max-width:1000px;margin:40px auto;padding:20px;color:#18302d}table{width:100%;border-collapse:collapse}th,td{padding:10px;border-bottom:1px solid #ddd;text-align:left}.report-metrics{display:flex;gap:30px}.report-metrics b{display:block;font-size:28px}.help{color:#647779}</style>${reportBody()}<p>생성일: ${new Intl.DateTimeFormat('ko-KR',{timeZone:'Asia/Seoul',dateStyle:'long'}).format(new Date())}</p></html>`,'text/html;charset=utf-8');toast('보고서를 다운로드했습니다.');}
function switchTab(tab){active=tab;document.querySelectorAll('.view').forEach(v=>v.hidden=v.id!==tab);document.querySelectorAll('nav button').forEach(b=>b.classList.toggle('active',b.dataset.tab===tab));$('#breadcrumb').textContent=titles[tab];$('#page-title').innerHTML=(tab==='overview'?'디지털 마케팅 통합 대시보드':titles[tab])+'<span class="title-dot">.</span>';}
document.addEventListener('click',async e=>{const t=e.target.closest('[data-tab]');if(t)switchTab(t.dataset.tab);const edit=e.target.closest('[data-edit]');if(edit)openEvent(events.find(v=>v.id===edit.dataset.edit));const del=e.target.closest('[data-delete]');if(del&&confirm('이 콘텐츠 일정을 삭제하시겠습니까?')){try{await repo.deleteEvent(del.dataset.delete);events=await repo.listEvents();render();toast('일정을 삭제했습니다.');}catch(err){toast('저장 실패: '+err.message);}}});
for(const id of ['year','month','channel'])$('#'+id).addEventListener('change',render);window.addEventListener('resize',()=>{if(records.length)render();});$('#download-top').onclick=reportDownload;$('#report-download').onclick=reportDownload;
$('#template').onclick=()=>download('마케팅_실적_양식.csv','\uFEFF월,채널,조회노출,참여,팔로워증가\r\n2026-11,유튜브,150000,3200,250\r\n2026-11,링크드인,90000,2100,180\r\n2026-11,인스타그램,120000,4000,300\r\n','text/csv;charset=utf-8');$('#export-data').onclick=()=>download('마케팅_전체데이터_백업.csv','\uFEFF월,채널,조회노출,참여,팔로워증가\r\n'+records.map(r=>[r.month,channels[r.channel].name,r.impressions,r.engagement,r.followers].join(',')).join('\r\n'),'text/csv;charset=utf-8');
async function upload(file){pending=[];$('#apply').hidden=true;$('#validation').textContent='파일을 검증하고 있습니다…';try{if(!file)throw Error('파일을 선택하세요.');if(file.size>5*1024*1024)throw Error('파일 크기는 최대 5MB입니다.');const ext=file.name.split('.').pop().toLowerCase();let rows;if(ext==='csv')rows=parseCSV(await file.text());else if(ext==='xlsx')rows=await readXLSX(await file.arrayBuffer());else throw Error('CSV 또는 .xlsx 파일만 지원합니다.');if(rows.length>10001)throw Error('최대 10,000행까지 가져올 수 있습니다.');const result=validateRows(rows);if(result.errors.length){$('#validation').innerHTML=`<b class="error">검증 실패 · ${result.errors.length}개 오류 · 데이터 미반영</b><ul class="error">${result.errors.slice(0,30).map(e=>`<li>${esc(e)}</li>`).join('')}</ul>`;return;}pending=result.records;$('#validation').innerHTML=`<b class="success">검증 완료 · ${pending.length}개 행</b><p class="help">${esc(file.name)} · 기존 월·채널 데이터는 대체됩니다. 아래 내용을 확인하고 반영하세요.</p><div class="table-wrap">${table(pending.slice(0,10))}</div>`;$('#apply').hidden=false;}catch(err){$('#validation').textContent='가져오기 실패: '+err.message;$('#validation').className='error';}}
$('#file').onchange=e=>upload(e.target.files[0]);const dz=$('#drop-zone');dz.ondragover=e=>{e.preventDefault();dz.classList.add('drag');};dz.ondragleave=()=>dz.classList.remove('drag');dz.ondrop=e=>{e.preventDefault();dz.classList.remove('drag');upload(e.dataTransfer.files[0]);};$('#apply').onclick=async()=>{try{await repo.importRecords(pending);records=await repo.listRecords();for(const y of [...new Set(records.map(r=>r.month.slice(0,4)))])if(![...$('#year').options].some(o=>o.value===y))$('#year').add(new Option(y,y));pending=[];$('#apply').hidden=true;$('#validation').innerHTML='<b class="success">데이터가 로컬 저장소에 반영되었습니다.</b>';render();toast('실적 데이터를 반영했습니다.');}catch(err){toast('저장 실패: '+err.message);}};
function openEvent(e){$('#event-form').reset();$('#event-id').value=e?.id||'';$('#dialog-title').textContent=e?'콘텐츠 일정 수정':'콘텐츠 일정 추가';$('#event-title').value=e?.title||'';$('#event-date').value=e?.date||`${year()}-${String(month()==='all'?11:month()).padStart(2,'0')}-01`;$('#event-channel').value=e?.channel||(channel()==='all'?'youtube':channel());$('#event-status').value=e?.status||'기획';$('#event-dialog').showModal();}$('#add-event').onclick=()=>openEvent();$('#close-dialog').onclick=()=>$('#event-dialog').close();$('#event-form').onsubmit=async e=>{e.preventDefault();if(!$('#event-title').value.trim())return;try{await repo.saveEvent({id:$('#event-id').value||crypto.randomUUID(),title:$('#event-title').value.trim(),date:$('#event-date').value,channel:$('#event-channel').value,status:$('#event-status').value});events=await repo.listEvents();$('#event-dialog').close();render();toast('일정을 저장했습니다. 선택한 기간 밖의 일정은 필터를 변경해 확인하세요.');}catch(err){toast('저장 실패: '+err.message);}};
try{repo=new LocalRepository();[records,events]=await Promise.all([repo.listRecords(),repo.listEvents()]);for(const y of [...new Set(records.map(r=>r.month.slice(0,4)))])if(![...$('#year').options].some(o=>o.value===y))$('#year').add(new Option(y,y));render();}catch(err){document.querySelectorAll('.view').forEach(v=>v.hidden=true);$('#overview').hidden=false;$('#overview').textContent='로컬 저장소를 열 수 없습니다: '+err.message;}
